message.content:
{
  "points": [
    {
      "grammar_point": "Participial phrase as adverbial clause",
      "sentence": "Having little or no money in my purse, and nothing particular to interest me on shore, I thought I would sail about a little...",
      "explanation": "El frase “Having little or no money in my purse, and nothing particular to interest me on shore” es una cláusula participial que funciona como modificador adverbial, indicando la condición bajo la cual el sujeto realiza la acción principal."
    },
    {
      "grammar_point": "Noun phrase with “of + gerund”",
      "sentence": "It is a way I have of driving off the spleen, and regulating the circulation.",
      "explanation": "En “a way I have of driving off the spleen, and regulating the circulation” el sustantivo “way” se complementa con la construcción “of + gerund” para expresar el medio o propósito de la acción."
    }
  ]
}

