message.content:
{
  "points": [
    {
      "grammar_point": "as + clause (simultaneous actions)",
      "sentence": "He heard whispers all around him as he sat eating between Ron and Hermione.",
      "explanation": "En esta oración, 'as' introduce una cláusula que indica que dos acciones ocurren al mismo tiempo: escuchar los susurros y estar sentado comiendo. Se traduce como 'mientras' en español."
    },
    {
      "grammar_point": "so that + clause (purpose)",
      "sentence": "The funny thing was that none of the whisperers seemed to mind him overhearing what they were saying about him — on the contrary, it was as though they were hoping he would get angry and start shouting again, so that they could hear his story firsthand.",
      "explanation": "La expresión 'so that' introduce una cláusula de propósito, indicando la intención de que los demás escucharan la historia directamente. En español se suele traducir como 'para que'."
    }
  ]
}

