message.content:
{
  "points": [
    {
      "grammar_point": "Parallelismo con listados de adverbios/adjetivos",
      "sentence": "Apple conducts business ethically, honestly, and in full compliance with the law.",
      "explanation": "Se usan varios modificadores coordinados (ethically, honestly, in full compliance) separados por comas y conectados con 'and' para mantener una estructura paralela que facilita la claridad y fluidez."
    },
    {
      "grammar_point": "Conjunción correlativa comparativa 'as ... as'",
      "sentence": "We believe that how we conduct ourselves is as critical to Apple’s success as making the best products in the world.",
      "explanation": "La construcción 'as … as' compara dos elementos (critical to Apple’s success y making the best products), indicando que ambos tienen la misma importancia."
    }
  ]
}

