{
  "points": [
    {
      "grammar_point": "Cláusula relativa no restrictiva con 'which'",
      "sentence": "This medicine contains Ibuprofen which belongs to a group of medicines called non-steroidal anti-inflammatory drugs (NSAIDs), which act to relieve pain and reduce swelling.",
      "explanation": "La cláusula introducida por 'which' añade información adicional y está separada por comas; no restringe el sustantivo sino que lo describe."
    },
    {
      "grammar_point": "Estructura paralela de infinitivos después de 'to'",
      "sentence": "It can be used to relieve headaches, rheumatic and muscular pain, pain from non‑serious arthritic conditions, backache, migraine, period pain, dental pain and neuralgia.",
      "explanation": "Tras 'to' se repite el infinitivo 'relieve' implícitamente, creando una lista paralela de acciones que facilita la comprensión."
    }
  ]
}

